async function zajel(){if(!me)return auth();getApp().innerHTML=shell("ZAJEL","الزاجل","اختر عضواً من اقتراحات السيرفر وأرسل باسمك أو مجهول.",'<form id="zf" class="form"><input id="zs" class="input" placeholder="اكتب اسم Discord"><div id="suggest" class="suggest"></div><input id="zu" type="hidden"><textarea id="zm" class="input" placeholder="الرسالة" required></textarea><div class="checks"><label><input type="radio" name="named" value="yes" checked> باسمي + منشن</label><label><input type="radio" name="named" value="no"> مجهول</label></div><button class="btn primary">إرسال</button></form>');let t;$("#zs").oninput=e=>{clearTimeout(t);t=setTimeout(async()=>{try{const d=await api("/api/public/members?q="+encodeURIComponent(e.target.value));$("#suggest").innerHTML=(d.members||[]).slice(0,8).map(m=>'<button type="button" data-z="'+m.id+'"><img src="'+esc(m.avatar)+'"><span>'+esc(m.name)+'<small>@'+esc(m.username)+"</small></span></button>").join("");$$("[data-z]").forEach(x=>x.onclick=()=>{const m=d.members.find(v=>v.id===x.dataset.z);$("#zu").value=m.username;$("#zs").value=m.name;$("#suggest").innerHTML=""})}catch{}},200)};$("#zf").onsubmit=async e=>{e.preventDefault();if(!$("#zu").value)return toast("اختر عضواً أولاً");try{await api("/api/zajel",{method:"POST",body:JSON.stringify({discordUsername:$("#zu").value,message:$("#zm").value,named:e.target.named.value==="yes"})});e.target.reset();toast("تم إرسال الزاجل")}catch(x){toast(x.message)}}}
