async function ownerPanel(k){const o=$("#ownerpanel");try{if(k==="logs"){const d=await api("/api/owner/logs");o.innerHTML='<div class="logs">'+d.map(x=>'<details><summary>'+esc(x.type)+' · '+esc(x.at)+'</summary><pre>'+esc(JSON.stringify(x.data,null,2))+"</pre></details>").join("")+"</div>"}else if(k==="zajel"){const d=await api("/api/owner/zajel");o.innerHTML='<div class="logs">'+d.map(x=>'<article><b>'+esc(x.senderName)+' → '+esc(x.targetName)+'</b><p>'+esc(x.message)+'</p><small>'+esc(x.at)+"</small></article>").join("")+"</div>"}else if(k==="accounts"){const d=await api("/api/owner/accounts");o.innerHTML='<div class="list">'+d.map(u=>'<div class="row"><div><b>'+esc(u.displayName)+'</b><small>@'+esc(u.username)+' · '+esc(u.role)+'</small></div>'+button(u.role==="admin"?"إزالة الإدارة":"منح الإدارة","admin:"+u.id,"ghost")+button("محادثاته","inspect:"+u.id,"primary")+button("حذف نهائي","del:"+u.id,"danger")+"</div>").join("")+"</div>"}else if(k==="applications"){const d=await api("/api/owner/applications");o.innerHTML='<div class="list">'+d.map(a=>'<article class="application"><b>'+esc(a.name)+'</b><pre>'+esc(JSON.stringify(a.answers,null,2))+"</pre>"+button("قبول","accept:"+a.id,"primary")+button("رفض","reject:"+a.id,"danger")+"</article>").join("")+"</div>"}else if(k==="groups"){const d=await api("/api/admin/groups");o.innerHTML='<div class="list">'+d.groups.filter(g=>g.status==="pending").map(g=>'<div class="row"><div><b>'+esc(g.name)+'</b><small>'+esc(g.ownerName)+'</small></div>'+button("قبول","gok:"+g.id,"primary")+button("رفض","gno:"+g.id,"danger")+"</div>").join("")||'<div class="empty">لا توجد طلبات</div>'+"</div>"}else if(k==="private"){o.innerHTML='<div class="empty">اختر حساباً من «الحسابات» لمشاهدة محادثاته.</div>'}else if(k==="subscriptions"){const [d,u]=await Promise.all([api("/api/owner/subscriptions"),api("/api/owner/accounts")]);o.innerHTML='<form id="subf" class="form"><select class="input" name="userId">'+u.map(x=>'<option value="'+x.id+'">'+esc(x.displayName)+'</option>').join("")+'</select><select class="input" name="bot"><option>حماية كاملة</option><option>ألعاب كاملة</option><option>بنك كامل</option><option>ستريك كامل</option><option>تذاكر وتقديم</option><option>برودكاست</option><option>قيفاوي</option></select><button class="btn primary">تفعيل</button></form><div class="list">'+d.map(x=>'<div class="row"><b>'+esc(x.bot)+'</b><span>'+esc(x.active?"فعال":"ملغى")+'</span>'+button(x.active?"إلغاء":"تفعيل","sub:"+x.id,"ghost")+"</div>").join("")+"</div>";$("#subf").onsubmit=async e=>{e.preventDefault();await api("/api/owner/subscriptions",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});ownerPanel(k)}}else if(k==="cinema"){const d=await api("/api/cinema"),status=await api("/api/cinema/status").catch(()=>({}));o.innerHTML='<div class="cinema-status">روم التشغيل: '+esc(status.voiceChannel?.name||"غير محدد")+' · Discord '+(status.discordConnected?"متصل":"غير متصل")+'</div><div class="list">'+d.map(x=>'<div class="row"><b>'+esc(x.title)+'</b><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">فتح الرابط</a>'+button("حذف","cinema-delete:"+x.id,"danger")+'</div>').join("")+'</div><form id="owner-cinema-form" class="form"><h3>إضافة للمكتبة</h3><input class="input" name="title" placeholder="العنوان" required><input class="input" name="url" type="url" placeholder="رابط HTTP/HTTPS" required><textarea class="input" name="description" placeholder="الوصف"></textarea><button class="btn primary">إضافة</button></form>';$("#owner-cinema-form").onsubmit=async e=>{e.preventDefault();try{await api("/api/cinema",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});ownerPanel(k)}catch(x){toast(x.message)}};$("[data-action^=cinema-delete:]").forEach(b=>b.onclick=async()=>{try{await api("/api/cinema/"+b.dataset.action.slice(14),{method:"DELETE"});ownerPanel(k)}catch(e){toast(e.message)}})}else if(k==="bots"){const d=await api("/api/owner/bots");o.innerHTML='<div class="list">'+d.map(b=>'<div class="row"><div><b>'+esc(b.botName)+'</b><small>'+esc(b.owner)+' · '+esc(b.guildId)+' · '+esc(b.status)+'</small></div></div>').join("")+'</div>'||'<div class="empty">لا توجد بوتات مسجلة.</div>'}else if(k==="settings"){const d=await api("/api/owner/settings");o.innerHTML='<form id="sf" class="form"><input class="input" name="announcement" value="'+esc(d.announcement||"")+'"><input class="input" name="announcementColor" value="'+esc(d.announcementColor||"#c7b2bb")+'"><button class="btn primary">حفظ</button></form>';$("#sf").onsubmit=async e=>{e.preventDefault();await api("/api/owner/settings",{method:"PATCH",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$("#announcement-text").textContent=e.target.announcement.value;$("#announcement-text").style.color=e.target.announcementColor.value||"#c7b2bb";toast("تم الحفظ")}}else if(k==="questions"){const d=await api("/api/applications/questions");o.innerHTML='<form id="qf" class="form"><textarea class="input" name="questions">'+esc(d.questions.join("\n"))+'</textarea><button class="btn primary">حفظ الأسئلة</button></form>';$("#qf").onsubmit=async e=>{e.preventDefault();await api("/api/owner/questions",{method:"PATCH",body:JSON.stringify({questions:e.target.questions.value.split("\n").map(x=>x.trim()).filter(Boolean)})});toast("تم حفظ الأسئلة")}}}catch(e){o.innerHTML='<div class="empty">'+esc(e.message)+"</div>"}}
async function ownerAction(a){try{if(a.startsWith("admin:")){const id=a.slice(6);const users=await api("/api/owner/accounts"),u=users.find(x=>x.id===id);if(u.role==="admin")await api("/api/owner/admins/"+id,{method:"DELETE"});else await api("/api/owner/admins",{method:"POST",body:JSON.stringify({userId:id})});ownerPanel("accounts")}else if(a.startsWith("del:")){if(confirm("حذف نهائي؟")){await api("/api/owner/accounts/"+a.slice(4),{method:"DELETE"});ownerPanel("accounts")}}else if(a.startsWith("inspect:")){const d=await api("/api/owner/user/"+a.slice(8)+"/private");$("#ownerpanel").innerHTML=d.map(c=>'<article class="panel"><h2>'+esc(c.name)+'</h2><div class="chat">'+c.messages.map(m=>'<div><b>'+esc(m.name)+'</b><p>'+esc(m.message)+'</p></div>').join("")+"</div></article>").join("")||'<div class="empty">لا توجد محادثات</div>'}else if(a.startsWith("accept:")||a.startsWith("reject:")){const id=a.split(":")[1];await api("/api/applications/"+id+"/status",{method:"PATCH",body:JSON.stringify({status:a.startsWith("accept:")?"accepted":"rejected"})});if(location.hash==="#admin")admin();else ownerPanel("applications")}else if(a.startsWith("gok:")||a.startsWith("gno:")){const id=a.split(":")[1];await api("/api/admin/groups/"+id+"/status",{method:"POST",body:JSON.stringify({status:a.startsWith("gok:")?"approved":"rejected"})});ownerPanel("groups")}else if(a.startsWith("sub:")){const id=a.slice(4),d=await api("/api/owner/subscriptions");const x=d.find(v=>v.id===id);await api("/api/owner/subscriptions/"+id,{method:"PATCH",body:JSON.stringify({active:!x.active})});ownerPanel("subscriptions")}}catch(e){toast(e.message)}}
function logout(){token="";me=null;localStorage.removeItem("mld_token");nav();go("home");toast("تم تسجيل الخروج")}
const pages={home,members,top,roles,chat,profile,zajel,games:gamesPage,groups,cinema,tickets,applications,reviews,account,admin,owner,ai,bots};
async function page(){let p=location.hash.slice(1)||"home";if(p==="logout"){logout();return}if(!pages[p]){p="home";if(location.hash!=="#home")history.replaceState(null,"","#home")}if(publicChatPoll){clearInterval(publicChatPoll);publicChatPoll=null}if(privateChatPoll){clearInterval(privateChatPoll);privateChatPoll=null}$("#mobile").classList.remove("open");nav();const menu=$("#menu");if(menu)menu.setAttribute("aria-expanded","false");getApp().setAttribute("aria-live","polite");try{await pages[p]()}catch(e){getApp().innerHTML='<div class="page"><div class="empty" role="alert">'+esc(e.message||"حدث خطأ غير متوقع")+"</div></div>"}}
let audioContext;function playUiSound(kind="click"){try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;audioContext=audioContext||new Ctx();if(audioContext.state==="suspended")audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;osc.type="sine";osc.frequency.setValueAtTime(kind==="success"?740:kind==="error"?220:480,now);osc.frequency.exponentialRampToValueAtTime(kind==="success"?980:kind==="error"?160:360,now+0.055);gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(kind==="success"?0.035:0.018,now+0.008);gain.gain.exponentialRampToValueAtTime(0.0001,now+0.075);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+0.08)}catch{}}
document.addEventListener("click",e=>{if(e.target.closest("button,.btn,[data-page]"))playUiSound("click");const p=e.target.closest("[data-page]");if(p){e.preventDefault();go(p.dataset.page);return}const a=e.target.closest("[data-action]");if(a){const v=a.dataset.action;if(v.startsWith("owner:"))ownerAction(v.slice(6));else if(v==="new-group")newGroup();else if(v.startsWith("create:"))createGame(v.slice(7));else if(v.startsWith("sessions:"))sessions(v.slice(9));else if(v.startsWith("join:")){}else if(v.startsWith("cinema-delete:")){}else if(v.startsWith("cinema-start:")){}else if(v.startsWith("bot-delete:")){}else if(/^(admin:|del:|inspect:|accept:|reject:|gok:|gno:|sub:)/.test(v))ownerAction(v);else if(pages[v])go(v); }});
$("#menu").onclick=()=>{const mobile=$("#mobile");if(!mobile)return;const open=mobile.classList.toggle("open");$("#menu").setAttribute("aria-expanded",String(open));};$("#modal-close").onclick=closeModal;$("#modal").onclick=e=>{if(e.target.id==="modal")closeModal()};
$("#theme")?.addEventListener("click",()=>{const next=document.documentElement.dataset.theme==="light"?"dark":"light";document.documentElement.dataset.theme=next;localStorage.setItem("mld_theme",next);$("#theme").textContent=next==="light"?"☀":"◐";toast(next==="light"?"تم تفعيل الوضع الفاتح":"تم تفعيل الوضع الليلي")});
if($("#theme"))$("#theme").textContent=document.documentElement.dataset.theme==="light"?"☀":"◐";
window.addEventListener("hashchange",page);
async function boot(){
  getApp();
  if(!app){document.body.insertAdjacentHTML("beforeend",'<main id="app" style="padding:40px;color:white">MLD</main>');getApp();}
  try{me=(await api("/api/auth/me")).user}catch{}
  try{nav()}catch(e){console.error("MLD nav error",e)}
  try{const s=await api("/api/settings");const a=$("#announcement-text");if(a){a.textContent=s.announcement||"مرحباً بكم في MLD";a.style.color=s.announcementColor||"#c7b2bb"}}catch(e){console.warn("MLD settings error",e)}
  try{await page()}catch(e){console.error("MLD page error",e);getApp().innerHTML='<div class="page"><div class="empty">'+esc(e.message||e)+"</div></div>"}
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",boot,{once:true});else boot();